begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table identity_gradebook_fixture(source uuid,mark uuid,selections jsonb);grant select,insert,update on identity_gradebook_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9f100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Identity review course','School identity scope','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','9f110000-0000-4000-8000-000000000001','9f100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Identity review task','School work',10,'61000000-0000-4000-8000-000000000001',2);
update app.people set display_name=(select display_name from app.people where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012')where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000018';
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
insert into identity_gradebook_fixture(source)select internal.create_learning_submission('9f110000-0000-4000-8000-000000000001','Exact identity source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update identity_gradebook_fixture set mark=internal.mark_submission(source,0,'Reviewed school source',2,0,true);
update identity_gradebook_fixture set selections=jsonb_build_array(jsonb_build_object('markingId',mark,'submissionId',source,'expectedRevision',1,'expectedSubmissionRevision',1,'expectedPolicyVersion',2,'parentVisible',false));
select is(internal.read_course_gradebook('9f100000-0000-4000-8000-000000000001',1,1,null,null)->'items'->0->>'identityRequiresReview','true','Duplicate current class peer beyond the one-row page requires identity review');
select throws_ok($$select internal.preview_gradebook_release('9f100000-0000-4000-8000-000000000001',(select selections from identity_gradebook_fixture))$$,'22023',null,'Ambiguous human identity cannot be confirmed through selected release preview');
select throws_ok($$select internal.release_gradebook_selection('9f100000-0000-4000-8000-000000000001',jsonb_build_object('selections',(select selections from identity_gradebook_fixture),'confirmRelease',true),'gradebook-identity-denied',repeat('a',64),'gradebook-identity')$$,'22023',null,'Direct selected release also checks current cross-page identity');
select lives_ok($$select internal.read_gradebook_source((select source from identity_gradebook_fixture))$$,'Exact authorized source remains available for individual human review');
reset role;
select is((select count(*)from app.result_revisions where assessment_id='9f110000-0000-4000-8000-000000000001'),0::bigint,'Ambiguous selected release creates no result');
update app.enrollments set effective_to=now()-interval '1 minute'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000018';
set local role cuevo_api;
select is(internal.read_course_gradebook('9f100000-0000-4000-8000-000000000001',1,1,null,null)->'items'->0->>'identityRequiresReview','false','Withdrawn same-name peer cannot create current identity ambiguity');
select lives_ok($$select internal.preview_gradebook_release('9f100000-0000-4000-8000-000000000001',(select selections from identity_gradebook_fixture))$$,'Resolved current identity permits reviewed preview');
reset role;
select ok(not has_function_privilege('cuevo_api','internal.gradebook_identity_requires_review(uuid,uuid,uuid)','EXECUTE')and not has_function_privilege('authenticated','internal.gradebook_identity_requires_review(uuid,uuid,uuid)','EXECUTE'),'No raw browser/runtime peer identity helper grant');
select*from finish();rollback;
